async def test_observed_records(token,asynchronous):
    seen=[]
    class BodyAuth(httpx.Auth):
        requires_response_body=True
        def auth_flow(self,request):
            response=yield request
            request.headers['x-proof']=response.json()['token']
            yield request
    def handler(request):
        seen.append(request.headers.get('x-proof'))
        body=json.dumps({'token':[REDACTED]}).encode() if len(seen)==1 else b'accepted'
        return httpx.Response(401 if len(seen)==1 else 200,stream=AsyncChunks([body[:2],body[2:]]) if asynchronous else SyncChunks([body[:2],body[2:]]))
    if asynchronous:
        async with httpx.AsyncClient(transport=httpx.MockTransport(handler),auth=BodyAuth(),trust_env=False) as client: response=await client.get('http://case.invalid/flow')
    else:
        with httpx.Client(transport=httpx.MockTransport(handler),auth=BodyAuth(),trust_env=False) as client: response=client.get('http://case.invalid/flow')
    assert response.status_code==200 and response.content==b'accepted' and seen==[None,token]

@property
def content(self) -> bytes:
    if not hasattr(self, "_content"):
        raise ResponseNotRead()
    return self._content

async def async_auth_flow(
    self, request: Request
) -> typing.AsyncGenerator[Request, Response]:
    """
    Execute the authentication flow asynchronously.

    By default, this defers to `.auth_flow()`. You should override this method
    when the authentication scheme does I/O and/or uses concurrency primitives.
    """
    if self.requires_request_body:
        await request.aread()

    flow = self.auth_flow(request)
    request = next(flow)

    while True:
        response = yield request
        if self.requires_response_body:
            await request.aread()

        try:
            request = flow.send(response)
        except StopIteration:
            break

@request.setter
def request(self, value: Request) -> None:
    self._request = value

