@pytest.mark.parametrize('pairs',[(('first','1'),('second','2')),(('alpha','a'),('beta','b'),('gamma','g')),(('left','x'),('right','y'))])
def test_observed_records(pairs):
    seen=[]
    def handler(request):
        seen.append(request)
        if len(seen)==1:
            headers=[('Set-Cookie',name+'='+value+'; Path=/; Expires=Wed, 09 Jun 2038 10:18:14 GMT') for name,value in pairs]
            return httpx.Response(200,headers=headers,text='stored')
        return httpx.Response(200,json={'cookie':request.headers.get('cookie','')})
    with httpx.Client(transport=httpx.MockTransport(handler),trust_env=False) as client:
        first=client.get('http://case.invalid/set')
        assert dict(first.cookies)==dict(pairs) and dict(client.cookies)==dict(pairs)
        second=client.get('http://case.invalid/check')
    jar=SimpleCookie(); jar.load(second.json()['cookie'])
    assert {name:m.value for name,m in jar.items()}==dict(pairs)

@pytest.mark.parametrize('pairs',[(('first','1'),('second','2')),(('alpha','a'),('beta','b'),('gamma','g')),(('left','x'),('right','y'))])
def test_observed_records(pairs):
    seen=[]
    def handler(request):
        seen.append(request)
        if len(seen)==1:
            headers=[('Set-Cookie',name+'='+value+'; Path=/; Expires=Wed, 09 Jun 2038 10:18:14 GMT') for name,value in pairs]
            return httpx.Response(200,headers=headers,text='stored')
        return httpx.Response(200,json={'cookie':request.headers.get('cookie','')})
    with httpx.Client(transport=httpx.MockTransport(handler),trust_env=False) as client:
        first=client.get('http://case.invalid/set')
        assert dict(first.cookies)==dict(pairs) and dict(client.cookies)==dict(pairs)
        second=client.get('http://case.invalid/check')
    jar=SimpleCookie(); jar.load(second.json()['cookie'])
    assert {name:m.value for name,m in jar.items()}==dict(pairs)

def __init__(self, cookies: CookieTypes | None = None) -> None:
    if cookies is None or isinstance(cookies, dict):
        self.jar = CookieJar()
        if isinstance(cookies, dict):
            for key, value in cookies.items():
                self.set(key, value)
    elif isinstance(cookies, list):
        self.jar = CookieJar()
        for key, value in cookies:
            self.set(key, value)
    elif isinstance(cookies, Cookies):
        self.jar = CookieJar()
        for cookie in cookies.jar:
            self.jar.set_cookie(cookie)
    else:
        self.jar = cookies

@property
def reason_phrase(self) -> str:
    try:
        reason_phrase: bytes = self.extensions["reason_phrase"]
    except KeyError:
        return codes.get_reason_phrase(self.status_code)
    else:
        return reason_phrase.decode("ascii", errors="ignore")

@classmethod
def get_reason_phrase(cls, value: int) -> str:
    try:
        return codes(value).phrase  # type: ignore
    except ValueError:
        return ""

@property
def cookies(self) -> Cookies:
    if not hasattr(self, "_cookies"):
        self._cookies = Cookies()
        self._cookies.extract_cookies(self)
    return self._cookies

def __repr__(self) -> str:
    cookies_repr = ", ".join(
        [
            f"<Cookie {cookie.name}={cookie.value} for {cookie.domain} />"
            for cookie in self.jar
        ]
    )

    return f"<Cookies[{cookies_repr}]>"

@property
def cookies(self) -> Cookies:
    """
    Cookie values to include when sending requests.
    """
    return self._cookies

@property
def headers(self) -> Headers:
    """
    HTTP headers to include when sending requests.
    """
    return self._headers

